import{_ as d,o as a,a as e,b as r}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"总体说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/overall_description"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/overall_description.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/overall_description.md","outlineHeaders":[{"level":2,"title":"GM->L1 Buffer的接口分类与使用场景","slug":"GM->L1-Buffer的接口分类与使用场景","link":"#GM->L1-Buffer的接口分类与使用场景"},{"level":2,"title":"UB->L1 Buffer的接口分类与使用场景","slug":"UB->L1-Buffer的接口分类与使用场景","link":"#UB->L1-Buffer的接口分类与使用场景"},{"level":2,"title":"L1 Buffer->L0A/B Buffer的接口分类与使用场景","slug":"L1-Buffer->L0A/B-Buffer的接口分类与使用场景","link":"#L1-Buffer->L0A/B-Buffer的接口分类与使用场景"},{"level":2,"title":"辅助配置接口说明","slug":"辅助配置接口说明","link":"#辅助配置接口说明"}],"lastUpdated":1788515292000}'),f={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/overall_description.md"};function o(B,t,u,L,h,l){return a(),e("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>总体说明<span id="ZH-CN_TOPIC_0000002569070899"></span></h1><p>矩阵计算的搬入是Ascend C编程框架中用于数据搬运的一类核心接口，主要实现Global Memory到L0A Buffer/L0B Buffer之间的数据高效传输。该类接口提供了多种数据搬运模式，能够满足矩阵计算中左右矩阵等数据的搬运需求，通常与Mmad接口配合使用。</p><p>矩阵计算的搬入的接口支持多种数据搬运场景，包括但不限于<strong>二维格式数据搬运、三维格式转换、压缩数据解压、矩阵转置搬运以及稀疏化数据处理</strong>等。通过灵活配置不同的参数结构体，开发者可以精确控制数据的搬运路径、起始位置、搬运长度等关键信息，充分利用硬件的数据搬运能力，最大化算子的整体执行性能。</p><p>矩阵计算的搬入接口支持多种数据通路，每种通路对应特定的存储层级和访问特性。</p><p><strong>表1</strong> <strong>数据通路和存储层级</strong></p><p><span id="zh-cn_topic_0000002543771563_table3523123518108"></span></p><table><thead><tr><th>源位置</th><th>源地址对齐要求</th><th>目的位置</th><th>目的地址对齐要求</th><th>典型应用场景</th></tr></thead><tbody><tr><td>Global Memory</td><td>1字节</td><td>L1 Buffer(A1)</td><td>32字节</td><td>从全局内存加载左矩阵数据到L1 Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L1 Buffer(B1)</td><td>32字节</td><td>从全局内存加载右矩阵数据到L1 Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L0A Buffer(A2)</td><td>512字节</td><td>从全局内存加载左矩阵数据到L0A Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L0B Buffer(B2)</td><td>512字节</td><td>从全局内存加载右矩阵数据到L0B Buffer。</td></tr><tr><td>L1 Buffer(A1)</td><td>32字节</td><td>L0A Buffer(A2)</td><td>512字节</td><td>从L1 Buffer加载左矩阵数据到L0A Buffer。</td></tr><tr><td>L1 Buffer(B1)</td><td>32字节</td><td>L0B Buffer(B2)</td><td>512字节</td><td>从L1 Buffer加载右矩阵数据到L0B Buffer。</td></tr><tr><td>L1 Buffer</td><td>32字节</td><td>BiasTable Buffer</td><td>64字节</td><td>从L1 Buffer加载存储矩阵计算所需的Bias（偏置）数据到BiasTable Buffer。</td></tr><tr><td>L1 Buffer</td><td>32字节</td><td>Fixpipe Buffer</td><td>128字节</td><td>从L1 Buffer加载Fixpipe搬运过程中所需的量化参数等数据到Fixpipe Buffer。</td></tr></tbody></table><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Ascend 950PR/Ascend 950DT因硬件变更，删除GM到L0A Buffer、L0B Buffer的数据通路。产生的影响是原GM到L0A Buffer和L0B Buffer的数据搬运需要拆分为两步，即从GM到L1 Buffer的数据搬运和从L1 Buffer到L0A Buffer、L0B Buffer的数据搬运。</p></div></div><h2 id="GM-&gt;L1-Buffer的接口分类与使用场景">GM-&gt;L1 Buffer的接口分类与使用场景<span id="zh-cn_topic_0000002543771563_section_gm2l1"></span><a class="header-anchor" href="#GM-&gt;L1-Buffer的接口分类与使用场景">​</a></h2><p><strong>表2</strong> <strong>GM-&gt;L1 Buffer接口</strong></p><p><span id="zh-cn_topic_0000002543771563_table18501247192710"></span></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="DataCopy_GMToL1_continuous.html">DataCopy（GMToL1连续数据搬运）</a></td><td>将矩阵从Global Memory连续搬运至L1 Buffer，格式和内容保持不变。</td><td>GM-&gt;L1 Buffer</td><td>矩阵计算数据从片外搬入L1 Buffer。</td></tr><tr><td><a href="DataCopy_GMToL1_highdim_split.html">DataCopy（GMToL1高维切分数据搬运）</a></td><td>从GM搬运至L1 Buffer，支持通过配置数据块个数、长度、地址间隔实现非连续搬运。</td><td>GM-&gt;L1 Buffer</td><td>矩阵分片、多通道数据的非连续搬运。</td></tr><tr><td><a href="DataCopy_GMToL1_ND2NZ.html">DataCopy（GMToL1随路转换-ND2NZ搬运）</a></td><td>从GM搬运至L1 Buffer，搬运同时完成ND到NZ分形格式的转换。</td><td>GM-&gt;L1 Buffer</td><td>矩阵计算前将ND格式特征图转为NZ分形格式。</td></tr><tr><td><a href="LoadData_GMToL1_2D.html">LoadData（GMToL1-2D矩阵搬运）</a></td><td>以512B数据分形为单位，将2D格式矩阵数据从GM搬运至L1 Buffer。</td><td>GM-&gt;L1 Buffer</td><td>普通矩阵计算所需的2D分形数据搬入L1 Buffer。</td></tr></tbody></table><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，新增GM-&gt;L1 Buffer如下接口，请开发者参考表3。</p><p><strong>表3</strong> <strong>GM-&gt;L1 Buffer接口</strong></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="DataCopy_GMToL1_DN2NZ.html">DataCopy（GMToL1随路转换-DN2NZ搬运）</a></td><td>从GM搬运至L1 Buffer，搬运同时完成DN到NZ格式的转换。</td><td>GM-&gt;L1 Buffer</td><td>DN格式权重数据搬入L1 Buffer并转换为NZ格式。</td></tr><tr><td><a href="DataCopyPad_GMToL1.html">DataCopyPad（GMToL1非对齐数据搬运）</a></td><td>将数据从GM非对齐搬运至L1 Buffer，支持在数据左/右侧自行填充。</td><td>GM-&gt;L1 Buffer</td><td>GM中非对齐数据搬入L1 Buffer时进行补齐。</td></tr><tr><td><a href="LoadData_GMToL1_2DV2.html">LoadData（GMToL1-2D矩阵搬运V2）</a></td><td>使用2DV2指令以512B分形为单位搬运2D格式数据从GM到L1 Buffer。</td><td>GM-&gt;L1 Buffer</td><td>矩阵计算2D分形数据从GM搬入L1 Buffer。</td></tr></tbody></table></div><h2 id="UB-&gt;L1-Buffer的接口分类与使用场景">UB-&gt;L1 Buffer的接口分类与使用场景<span id="zh-cn_topic_0000002543771563_section_ub2l1"></span><a class="header-anchor" href="#UB-&gt;L1-Buffer的接口分类与使用场景">​</a></h2><p><strong>表4</strong> <strong>UB-&gt;L1 Buffer接口</strong></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="DataCopy_UBToL1_continuous.html">DataCopy（UBToL1连续数据搬运）</a></td><td>将数据从UB连续搬运至L1 Buffer，格式和内容保持不变。</td><td>UB-&gt;L1 Buffer</td><td>矢量计算结果从UB传入L1 Buffer供矩阵计算使用。</td></tr><tr><td><a href="DataCopy_UBToL1_highdim_split.html">DataCopy（UBToL1高维切分数据搬运）</a></td><td>从UB搬运至L1 Buffer，支持通过块参数配置实现非连续搬运。</td><td>UB-&gt;L1 Buffer</td><td>UB中非连续排列数据搬入L1 Buffer。</td></tr><tr><td><a href="DataCopy_UBToL1_ND2NZ.html">DataCopy（UBToL1随路转换-ND2NZ搬运）</a></td><td>从UB搬运至L1 Buffer，搬运同时完成ND到NZ分形格式转换。</td><td>UB-&gt;L1 Buffer</td><td>UB中ND格式数据搬入L1 Buffer并转为NZ格式。</td></tr><tr><td><a href="DataCopyPad_UBToL1.html">DataCopyPad（UBToL1非对齐数据搬运）</a></td><td>将数据从UB非对齐搬运至L1 Buffer，支持在数据左/右侧自行填充。</td><td>UB-&gt;L1 Buffer</td><td>UB中非32B对齐边界数据的搬移与补齐。</td></tr></tbody></table><h2 id="L1-Buffer-&gt;L0A/B-Buffer的接口分类与使用场景">L1 Buffer-&gt;L0A/B Buffer的接口分类与使用场景<span id="zh-cn_topic_0000002543771563_section_l12l0"></span><a class="header-anchor" href="#L1-Buffer-&gt;L0A/B-Buffer的接口分类与使用场景">​</a></h2><p><strong>表5</strong> <strong>L1 Buffer-&gt;L0A/B Buffer接口</strong></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="LoadData_2D.html">LoadData（2D矩阵搬运）</a></td><td>以512B分形为单位搬运2D格式矩阵数据，支持L1 Buffer-&gt;L0A Buffer/L0B Buffer通路及分形转置。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>矩阵计算数据从L1 Buffer搬入L0A Buffer/L0B Buffer计算缓冲区。</td></tr><tr><td><a href="LoadData_3D.html">LoadData（卷积数据搬运）</a></td><td>将NC1HWC0格式Feature Map完成Image to Column展开后，以512B分形为单位搬入L0A Buffer/L0B Buffer。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>卷积的im2col展开与矩阵计算数据搬入。</td></tr><tr><td><a href="LoadDataWithTranspose.html">LoadDataWithTranspose</a></td><td>搬运2D格式数据并伴随转置操作，将多个分形拼接为方块矩阵后转置再拆分搬入L0A Buffer/L0B Buffer。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>矩阵计算中需转置的A/B矩阵搬入L0 Buffer。</td></tr><tr><td><a href="DataCopy_L1ToBiasTable.html">DataCopy（L1ToBiasTable-Buffer数据搬运）</a></td><td>将矩阵计算的bias参数从L1 Buffer搬运至BiasTable Buffer。</td><td>L1 Buffer-&gt;BiasTable Buffer</td><td>矩阵乘后加偏置（bias add）参数搬入。</td></tr><tr><td><a href="DataCopy_L1ToFixpipe.html">DataCopy（L1ToFixpipe-Buffer数据搬运）</a></td><td>将随路量化和随路ReLU参数从L1 Buffer搬运至Fixpipe Buffer。</td><td>L1 Buffer-&gt;Fixpipe Buffer</td><td>矩阵计算结果的随路量化、激活参数搬入。</td></tr></tbody></table><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>针对Ascend 950PR/Ascend 950DT，LoadDataWithTranspose仅支持L1 Buffer-&gt;L0B Buffer通路，不支持L1 Buffer-&gt;L0A Buffer通路。</p></div></div><div data-filter="910b,A3"><p>针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品，支持L1 Buffer-&gt;L0B Buffer如下接口，请开发者参考表6。</p><p><strong>表6</strong> <strong>L1 Buffer-&gt;L0B Buffer接口</strong></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="LoadDataWithSparse.html">LoadDataWithSparse</a></td><td>搬运4选2结构化稀疏矩阵计算所需的稠密化权重矩阵和索引矩阵。</td><td>L1 Buffer-&gt;L0B Buffer</td><td>稀疏矩阵乘法计算数据搬入。</td></tr></tbody></table></div><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，新增L1 Buffer-&gt;L0A/B Buffer如下接口，请开发者参考表7。</p><p><strong>表7</strong> <strong>L1 Buffer-&gt;L0A/B Buffer接口</strong></p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="LoadData_2D_V2.html">LoadData（2D矩阵搬运V2）</a></td><td>以512B分形为单位搬运2D格式矩阵数据，使用V2参数结构，支持更多数据类型。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>矩阵计算数据搬入L0A Buffer/L0B Buffer，支持b4数据类型。</td></tr><tr><td><a href="LoadData_2D_BitMode.html">LoadData（BitMode2D矩阵搬运）</a></td><td>LoadData（2D矩阵搬运V2）的bit模式变体，支持按位操作的数据搬运。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>用于追求极致Scalar性能的普通矩阵数据搬运。</td></tr><tr><td><a href="LoadData_2D_MX.html">LoadData（MX矩阵搬运）</a></td><td>LoadData（2D矩阵搬运V2）的MX格式扩展，支持MX格式矩阵数据搬运。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>MX浮点格式的矩阵数据搬入。</td></tr><tr><td><a href="LoadData_3D_BitMode.html">LoadData（BitMode卷积数据搬运）</a></td><td>LoadData（卷积数据搬运）的bit模式变体，支持按位操作的3D数据搬运。</td><td>L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer</td><td>用于追求极致Scalar性能的卷积im2col展开与搬入。</td></tr></tbody></table></div><h2 id="辅助配置接口说明">辅助配置接口说明<span id="zh-cn_topic_0000002543771563_section_aux"></span><a class="header-anchor" href="#辅助配置接口说明">​</a></h2><p><strong>表8</strong> <strong>辅助配置接口</strong></p><p><span id="zh-cn_topic_0000002543771563_table107953337145"></span></p><table><thead><tr><th>接口名称</th><th>功能说明</th><th>配合使用的接口</th></tr></thead><tbody><tr><td><a href="../cube_load_aux_config/Fill.html">Fill</a></td><td>初始化设置L1 Buffer/L0A Buffer/L0B Buffer的值。</td><td>-</td></tr><tr><td><a href="../cube_load_aux_config/SetFmatrix.html">SetFmatrix</a></td><td>设置FeatureMap属性描述。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td><a href="../cube_load_aux_config/SetLoadDataBoundary.html">SetLoadDataBoundary</a></td><td>设置L1 Buffer边界值。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td><a href="../cube_load_aux_config/SetLoadDataRepeat.html">SetLoadDataRepeat</a></td><td>设置Repeat参数实现多迭代搬运。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td><a href="../cube_load_aux_config/SetLoadDataPaddingValue.html">SetLoadDataPaddingValue</a></td><td>设置Padding填充值。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td><a href="../cube_load_aux_config/LoadDataUnzip.html">LoadDataUnzip</a></td><td>将GM上的数据解压并搬运到L1 Buffer（A1/B1）或L0B Buffer（B2）上。</td><td>LoadUnzipIndex</td></tr><tr><td><a href="../cube_load_aux_config/LoadImageToLocal.html">LoadImageToLocal</a></td><td>将图像数据从Global Memory搬运到Local Memory。</td><td>SetAippFunctions</td></tr><tr><td><a href="../cube_load_aux_config/LoadUnzipIndex.html">LoadUnzipIndex</a></td><td>加载GM上的压缩索引表到内部寄存器。</td><td>-</td></tr><tr><td><a href="../cube_load_aux_config/SetAippFunctions.html">SetAippFunctions</a></td><td>设置图片预处理（AIPP，AI Core pre-process）相关参数。</td><td>LoadImageToLocal</td></tr></tbody></table></article></div>',1)])])}const s=d(f,[["render",o]]);export{p as __pageData,s as default};
